import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Cherry Studio","description":"在 Cherry Studio 中添加 Tokeness 自定义服务商，配置 API 地址、API Key 和模型列表。","frontmatter":{"title":"Cherry Studio","description":"在 Cherry Studio 中添加 Tokeness 自定义服务商，配置 API 地址、API Key 和模型列表。"},"headers":[],"relativePath":"zh/integrations/cherry-studio.md","filePath":"zh/integrations/cherry-studio.md","lastUpdated":1783490293000}'),s={name:"zh/integrations/cherry-studio.md"};function o(i,t,n,h,l,p){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="cherry-studio" tabindex="-1">Cherry Studio <a class="header-anchor" href="#cherry-studio" aria-label="Permalink to &quot;Cherry Studio&quot;">​</a></h1><p>Cherry Studio 支持自定义 AI Provider。Tokeness 按 OpenAI 兼容接口接入，在自定义服务商中填写 API 地址、API Key，再手动添加模型名。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>Provider Type</td><td><code>OpenAI</code> 或自定义 OpenAI 兼容服务商</td></tr><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>API Address / Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model ID</td><td>Tokeness 模型广场中的完整模型名</td></tr></tbody></table><p>不同版本的 Cherry Studio 字段名可能不同。只要字段含义是 API 地址、API Key、模型管理，就按上表填写。</p><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>先准备：</p><ol><li>一个 Cherry Studio 专用 API Key。</li><li>一个已确认可用的模型名。</li><li>可用余额。</li></ol><p>Key 名称可以写成：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cherry-studio-local</span></span></code></pre></div><p>如果你会在 Cherry Studio 里配置多个助手或知识库，可以为不同用途建立多个 Key。</p><h2 id="_2-新建自定义服务商" tabindex="-1">2. 新建自定义服务商 <a class="header-anchor" href="#_2-新建自定义服务商" aria-label="Permalink to &quot;2. 新建自定义服务商&quot;">​</a></h2><p>进入 Cherry Studio 设置，找到模型服务、Provider 或服务商配置。</p><p>新建服务商：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name: Tokeness</span></span>
<span class="line"><span>Type: OpenAI</span></span>
<span class="line"><span>API Address: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: 你的 Tokeness API Key</span></span></code></pre></div><p>保存前，如果界面有 Check、Test 或验证按钮，先点一次。验证失败时不要继续添加模型，先检查 Key 和 API 地址。</p><h2 id="_3-添加模型" tabindex="-1">3. 添加模型 <a class="header-anchor" href="#_3-添加模型" aria-label="Permalink to &quot;3. 添加模型&quot;">​</a></h2><p>Cherry Studio 的自定义 Provider 通常需要手动添加模型。</p><p>操作方式：</p><ol><li>打开 Tokeness 模型广场。</li><li>复制完整模型名。</li><li>回到 Cherry Studio 的模型管理。</li><li>点击添加模型。</li><li>粘贴模型名。</li><li>保存。</li></ol><p>模型名要完整保留大小写、供应商前缀和版本号。</p><h2 id="_4-设置默认模型" tabindex="-1">4. 设置默认模型 <a class="header-anchor" href="#_4-设置默认模型" aria-label="Permalink to &quot;4. 设置默认模型&quot;">​</a></h2><p>添加模型后，在 Cherry Studio 的对话页面选择 Tokeness Provider 和对应模型。</p><p>首次测试输入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只回复一句话，说明当前模型已经可用。</span></span></code></pre></div><p>然后打开 Tokeness 使用日志，确认请求进入 Tokeness。</p><h2 id="_5-多服务商配置" tabindex="-1">5. 多服务商配置 <a class="header-anchor" href="#_5-多服务商配置" aria-label="Permalink to &quot;5. 多服务商配置&quot;">​</a></h2><p>如果你有多种使用场景，可以创建多个 Tokeness Provider：</p><table tabindex="0"><thead><tr><th>供应商名称</th><th>用途</th></tr></thead><tbody><tr><td><code>Tokeness Chat</code></td><td>日常聊天</td></tr><tr><td><code>Tokeness Coding</code></td><td>代码相关对话</td></tr><tr><td><code>Tokeness Low Cost</code></td><td>摘要、翻译、简单问答</td></tr><tr><td><code>Tokeness Test</code></td><td>小额度测试</td></tr></tbody></table><p>这些 Provider 可以使用同一个 Base URL，只需要 Key 和模型配置不同。</p><h2 id="_6-排查" tabindex="-1">6. 排查 <a class="header-anchor" href="#_6-排查" aria-label="Permalink to &quot;6. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>Check 失败</td><td>检查 API 地址、Key、余额</td></tr><tr><td>401 Unauthorized</td><td>重新复制 API Key</td></tr><tr><td>404 Not Found</td><td>API 地址填写 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>模型列表为空</td><td>手动添加模型名</td></tr><tr><td>model not found</td><td>从模型广场重新复制模型名</td></tr><tr><td>Tokeness 无日志</td><td>当前会话没有选中 Tokeness Provider</td></tr><tr><td>消耗无法区分</td><td>为 Cherry Studio 单独建 Key</td></tr></tbody></table><h2 id="外部文档" tabindex="-1">外部文档 <a class="header-anchor" href="#外部文档" aria-label="Permalink to &quot;外部文档&quot;">​</a></h2><ul><li><a href="https://docs.cherry-ai.com/docs/en-us/pre-basic/providers/zi-ding-yi-fu-wu-shang" target="_blank" rel="noreferrer">Cherry Studio Custom Provider</a></li><li><a href="https://docs.cherry-ai.com/docs/en-us/pre-basic/providers/newapi" target="_blank" rel="noreferrer">Cherry Studio NewAPI Provider 示例</a></li></ul>`,34)])])}const y=e(s,[["render",o]]);export{u as __pageData,y as default};
